esPrompt":"¿Qué se practica en el audio?"}],"challenge":[{"type":"Final challenge","en":"Choose the word that belongs to colours.","es":"red","opts":["red","yellow","green"],"esPrompt":"Elige la palabra que pertenece a los colores.."},{"type":"Final challenge","en":"Which word completes this mission's vocabulary set?","es":"blue","opts":["blue","green","black"],"esPrompt":"¿Qué palabra completa el vocabulario de esta misión?"},{"type":"Final challenge","en":"Choose the correct word for the final mini-challenge.","es":"yellow","opts":["yellow","black","white"],"esPrompt":"Elige la palabra correcta para el mini-reto final."},{"type":"Final challenge","en":"Choose the word that belongs to colours.","es":"green","opts":["green","white","orange"],"esPrompt":"Elige la palabra que pertenece a los colores.."},{"type":"Final challenge","en":"Which word completes this mission's vocabulary set?","es":"black","opts":["black","orange","pink"],"esPrompt":"¿Qué palabra completa el vocabulario de esta misión?"},{"type":"Final challenge","en":"Choose the correct word for the final mini-challenge.","es":"white","opts":["white","pink","purple"],"esPrompt":"Elige la palabra correcta para el mini-reto final."},{"type":"Final challenge","en":"Choose the word that belongs to colours.","es":"orange","opts":["orange","purple","brown"],"esPrompt":"Elige la palabra que pertenece a los colores.."},{"type":"Final challenge","en":"Which word completes this mission's vocabulary set?","es":"pink","opts":["pink","brown","red"],"esPrompt":"¿Qué palabra completa el vocabulario de esta misión?"},{"type":"Final challenge","en":"Choose the correct word for the final mini-challenge.","es":"purple","opts":["purple","red","blue"],"esPrompt":"Elige la palabra correcta para el mini-reto final."},{"type":"Final challenge","en":"Choose the word that belongs to colours.","es":"brown","opts":["brown","blue","yellow"],"esPrompt":"Elige la palabra que pertenece a los colores.."}]};
const extraTexts={reading:"I can see colours in the garden. The sun is yellow. The sky is blue. The grass is green. I see a red flower and a white cloud. My ball is blue too. What is your favourite colour?",listening:"Look around! The sun is yellow, the sky is blue and the grass is green. Here is a red flower. I can see a white cloud. Now find something blue. Great listening!"};
function extraSpeak(text){if(!("speechSynthesis" in window))return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang="en-GB";u.rate=.82;speechSynthesis.speak(u)}
document.querySelectorAll(".pron-word").forEach(b=>b.addEventListener("click",()=>extraSpeak(b.dataset.pron)));
document.getElementById("play-003").addEventListener("click",()=>extraSpeak(extraTexts.listening));
document.getElementById("stop-003").addEventListener("click",()=>{if("speechSynthesis" in window)speechSynthesis.cancel()});
document.querySelectorAll(".extra-quiz").forEach(box=>{
 const key=box.dataset.extra, qs=extraSections[key], start=Number(box.dataset.start);
 let i=0,points=0,done=false;
 const q=box.querySelector(".extra-question"), answers=box.querySelector(".extra-answers"), feedback=box.querySelector(".extra-feedback"), next=box.querySelector(".extra-next"), counter=box.querySelector(".extra-counter"), bar=box.querySelector(".extra-bar"), audio=box.querySelector(".extra-audio");
 function render(){
  done=false;const item=qs[i];counter.textContent="Reto "+(start+i)+" de 100";bar.style.width=((start+i-1)/100*100)+"%";
  q.innerHTML="<span>"+item.en+"</span><span class=\"prompt-translation\" lang=\"es\">"+item.esPrompt+"</span>";feedback.textContent="";next.hidden=true;
  if(audio){audio.hidden=false;audio.onclick=()=>extraSpeak(item.en);}
  answers.innerHTML=[...item.opts].sort(()=>Math.random()-.5).map(o=>'<button type="button">'+o+'</button>').join("");
  answers.querySelectorAll("button").forEach(b=>b.onclick=()=>{
   if(done)return;done=true;const ok=b.textContent===item.es;if(ok)points++;
   feedback.textContent=ok?"✓ ¡Correcto!":"Respuesta correcta: "+item.es;
   feedback.style.color=ok?"#21845b":"#a34b42";
   answers.querySelectorAll("button").forEach(x=>{x.disabled=true;if(x.textContent===item.es)x.style.border="2px solid #21845b"});
   next.hidden=false;counter.textContent="Reto "+(start+i)+" de 100 · Aciertos en esta sección: "+points;
  });
 }
 next.addEventListener("click",()=>{
  if(i<qs.length-1){i++;render();}
  else{
   q.textContent="¡Has completado esta sección!";
   answers.innerHTML="";next.hidden=true;if(audio)audio.hidden=true;
   bar.style.width=((start+qs.length-1)/100*100)+"%";
   counter.textContent="Retos "+start+"–"+(start+qs.length-1)+" completados";
   feedback.textContent="Resultado: "+points+" de 10. "+(key==="listening"?"Ya puedes consultar la transcripción.":"¡Buen trabajo!");
   if(key==="listening")document.getElementById("transcript-003").hidden=false;
