const result=panel.querySelector("#speaking-result"),grid=panel.querySelector(".speaking-words"),prompt=panel.querySelector("#speaking-prompt"),status=panel.querySelector("#speaking-status"),feedback=panel.querySelector("#speaking-feedback"),record=panel.querySelector("#speaking-record"),stop=panel.querySelector("#speaking-stop");
