function safe(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function say(text){if(!("speechSynthesis"in window)){status.textContent="Tu navegador no permite reproducir voz.";return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang="en-GB";u.rate=.82;const v=speechSynthesis.getVoices().find(x=>x.lang?.toLowerCase()==="en-gb");if(v)u.voice=v;speechSynthesis.speak(u)}
function choose(index){if(busy)return;selected=source[index].word;prompt.textContent="Palabra "+(index+1)+" de "+source.length+": "+selected+". Escucha el modelo y después graba tu voz.";record.disabled=false;feedback.textContent="Palabra objetivo: "+selected+". Escucha el modelo de inglés británico y realiza la grabación cuando estés preparado.";result.hidden=false;grid.querySelectorAll("[data-select]").forEach((b,i)=>{b.textContent=i===index?"Palabra seleccionada":"Practicar esta palabra";b.setAttribute("aria-pressed",i===index?"true":"false")})}
grid.innerHTML=source.map((x,i)=>'<div class="pron-card"><div><b>'+safe(x.word)+'</b><span class="pron-cue">'+safe(readableCue[x.word.toLowerCase()]||x.cue||"Escucha el modelo")+'</span></div><div style="display:grid;gap:6px"><button type="button" data-listen="'+i+'">Escuchar modelo</button><button type="button" data-select="'+i+'" aria-pressed="false">Practicar esta palabra</button></div></div>').join("");
